export const messages = {
  th:{...Object.fromEntries(Object.keys(labels).map(key => [key, key])), ...orderThai, ...Object.fromEntries(Object.entries(errors).map(([key, text]) => [key, text[0]]))},
  en:{...labels, ...Object.fromEntries(Object.entries(errors).map(([key, text]) => [key, text[1]]))},
};
export function translate(locale, key, values = {}) {
  const text = messages[locale]?.[key] ?? messages.th[key] ?? key;
  return text.replace(/\{(\w+)\}/g, (match, name) => Object.hasOwn(values, name) ? String(values[name]) : match);
}
export function formatSatang(amount, locale = 'th') {
  assertSatang(amount);
  return new Intl.NumberFormat(locale === 'en' ? 'en-GB' : 'th-TH', {style:'currency', currency:'THB'})
    .formatToParts(Math.floor(amount / 100))
    .map(part => part.type === 'fraction' ? String(amount % 100).padStart(2, '0') : part.value).join('');
}
export function bahtInput(amount) {
  assertSatang(amount);
  return `${Math.floor(amount / 100)}.${String(amount % 100).padStart(2, '0')}`;
}
